def preserve_existing_submissions(apps, schema_editor):
    Availability = apps.get_model("shifts", "Availability")
    ShiftSubmission = apps.get_model("shifts", "ShiftSubmission")
    Membership = apps.get_model("accounts", "StoreMembership")
    alias = schema_editor.connection.alias
    memberships = {row["id"]: row for row in Membership.objects.using(alias).values("id", "user_id", "store_id")}
    by_user_store = {(row["user_id"], row["store_id"]): row["id"] for row in memberships.values()}
    grouped = {}
    for availability in Availability.objects.using(alias).all().iterator():
        membership_id = availability.membership_id or by_user_store.get((availability.user_id, availability.store_id))
        if membership_id not in memberships or not 2 <= availability.work_date.year <= 9998:
            continue
        month = availability.work_date.replace(day=1)
        grouped.setdefault((membership_id, month), []).append((availability.pk, availability.created_at))
    for (membership_id, month), records in grouped.items():
        last_saved = max(saved_at for _, saved_at in records)
        submission, _ = ShiftSubmission.objects.using(alias).get_or_create(
            membership_id=membership_id, target_month=month,
            defaults={"submission_mode": "availability", "is_submitted": True, "submitted_at": last_saved},
        )
        Availability.objects.using(alias).filter(pk__in=[pk for pk, _ in records]).update(
            submission_id=submission.pk, membership_id=membership_id,
        )


